\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f3\fs24 275r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f3\fs24\chcbpat17 Gaufridus de Monte Electo}}\plain \f3\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f3\fs24\chcbpat17 De auctoritate sacri concilii generalis}}\plain \f3\fs24  (Ausschnitt). 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f3\fs24\chcbpat17 Quia video nonnullos de veritate iuris forsitan minus informatos de potestate et auctoritate huius sacri concilii Basiliensis dubitare}}\plain \f3\fs24  \u8230 \'85 - \u8230 \'85 sanctorum patrum determinacionibus subiacere ne incurrant in casum capitulo 'Ne inniteris' de consti[tutionibus] [X 1.2.5] etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Auch in Wolfenb\u252 \'fcttel, HAB, mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 Cod. Guelf. 313 Helmst.}}\plain \f3\fs24  (Basel, 1436-38), 145v-146v, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f3\fs24\chcbpat17 Cod. Guelf. 376 Helmst.}}\plain \f3\fs24  (Basel, 1440-50), 249r-v, vgl. Beschreibung von Bertram Lesser (mit weiterer Lit.): http://diglib.hab.de/?db=mss&list=ms&id=313-helmst&catalog=Lesser.}

