\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 117vb}}\plain \f1\lang1033\fs24 : \plain \f1\b\lang1033\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Agilinus}}\plain \f1\b\lang1033\fs24 ], {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De contentis urinarum}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item vnus athomus uel duo paruissimi nigri significant dolorem}}\plain \f1\i\lang1033\fs24  alicuius \plain \f1\lang1033\fs24 [?]\plain \f1\i\lang1033\fs24  ypocundrij dextri uel sinitri. \endash  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item contentum spermaticum longum in forma pili et tandem quasi trumbosum}}\plain \f1\i\lang1033\fs24 , id est grossum in fundo vasis at testari habet dolorem membrorum iuncturalium, id est arthericam. \endash  Item contentum residens in fundo vrinalis \plain \f1\lang1033\fs24 [?] \plain \f1\i\lang1033\fs24 grossum album trumbosum quasi massa carnis significat dissolucionem siue decisionum a renibus ... - ... significant dissolucionem tocius corporis vniuersalem. Expliciunt contenta magistri Galteri.\plain \f1\lang1033\fs24  \endash  Rest der Spalte leer. 
\par \pard\fi0\li0\qj\ri0\sb60\sa60\itap0 \plain \f1\lang1033\fs20 Literatur: Vgl. Thorndike/Kibre, Catalogue of Incipits of Medieval Scientific Writings, Sp. 1398,7; 1399,13, dort jedoch erheblich abweichende Initien. }

