\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 133r\endash 137v}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de triplici modo conficiendi vini}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (133r) Inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [B]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 eatissime pater non est indecens de vinis legere cum }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [?]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  vinum sit, quod}}\plain \f1\i\lang1033\fs24  ... - ... Et dicit Macrobius, quod succus eius bibitus prestat victoriam, quam deus concedat regi nostro inclito domino, cui benedicat deus. Amen. 
\par \pard\fi0\li0\qj\ri0\sb60\sa60\itap0 \plain \f1\lang1033\fs20 Als Autor im Text ein \plain \f1\i\lang1033\fs20 magister Raynaldus de Villa Nova \plain \f1\lang1033\fs20 genannt. \endash  Parallel\u252 \'fcberlieferung: Vatikanstadt, Vatikanische Apostolische Bibliothek, Vat. lat. 3714 (online: https://digi.vatlib.it/view/MSS_Vat.lat.3714), fol. 67v, dort der Text ebenfalls Raynaldus de Villa Nova zugewiesen, vgl. das Explicit auf fol. 91r: \plain \f1\i\lang1033\fs20 Explicit liber vinorum compositus a magistro Raynaldo de Uilla Noua. Deo gratias. Amen. \plain \f1\lang1033\fs20 \endash  Literatur: (mit Verweis auf den Cod. Vat. lat. 3714:) Marilyn Nicoud, Les r\u233 \'e9gimes de sant\u233 \'e9 au Moyen \u194 \'c2ge, Kapitel X (Chapitre X. Le livre di\u233 \'e9t\u233 \'e9tique: manuscrits et imprim\u233 \'e9s), Anm. 206.}

